import type { Source } from "./Core";
/**
 * Callbag operator that applies a transformation on data passing through it.
 * Works on either pullable or listenable sources.
 *
 * Adapted from https://github.com/staltz/callbag-map
 *
 * Marble diagram:
 *   " a  b  c  |"
 *   {map((x) => x + "0")}
 *   " a0 b0 c0 |"
 *
 * @param f The function that transforms the data elements
 *     in the stream using the function provided.
 * @returns A callbag operator that transforms data in the
 *     stream using the function provided.
 *
 * @internal
 */
export declare const map: <T, U, E>(f: (data: T) => U) => (source: Source<T, E>) => Source<U, E>;
